<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kiln Yard — a three.js tactical FPS</title>
<style>
  /* One palette, six flat values, and the same six are the scene's colours in src/palette.js. */
  :root {
    --canvas: #14161a;
    --surface: #1e2228;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #e0632a;
    --ct: #4f9ec4;
    --t: #e0632a;
    --radius: 4px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0; height: 100%; overflow: hidden;
    background: var(--canvas); color: var(--ink); font-family: var(--font-ui);
    -webkit-font-smoothing: antialiased;
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; font-family: var(--font-ui); }

  /* ---- crosshair: four ticks that open with movement and bloom with recoil ---- */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 60px; height: 60px; transform: translate(-50%, -50%); }
  #crosshair i { position: absolute; background: var(--ink); box-shadow: 0 0 2px #0008; }
  #crosshair .c-t { left: 29px; width: 2px; height: 9px; }
  #crosshair .c-b { left: 29px; width: 2px; height: 9px; }
  #crosshair .c-l { top: 29px; height: 2px; width: 9px; }
  #crosshair .c-r { top: 29px; height: 2px; width: 9px; }
  #crosshair.hit .c-t, #crosshair.hit .c-b, #crosshair.hit .c-l, #crosshair.hit .c-r { background: var(--accent); }
  #crosshair.kill .c-t, #crosshair.kill .c-b, #crosshair.kill .c-l, #crosshair.kill .c-r { background: #ff5b45; }

  /* ---- top bar: score, round clock, round number ---- */
  #topbar {
    position: fixed; top: 18px; left: 50%; transform: translateX(-50%);
    display: grid; grid-template-columns: auto auto auto; align-items: center; gap: 18px;
    padding: 8px 14px; background: #14161ad9; border: 1px solid var(--hairline);
    border-radius: var(--radius); backdrop-filter: blur(6px);
  }
  .team-score { font-family: var(--font-readout); font-size: 26px; font-weight: 600; letter-spacing: -0.02em; }
  .team-score.ct { color: var(--ct); }
  .team-score.t { color: var(--t); }
  .team-tag { font-size: 10px; letter-spacing: 0.14em; color: var(--muted); text-align: center; }
  #clock { font-family: var(--font-readout); font-size: 22px; min-width: 62px; text-align: center; }
  #clock.low { color: var(--accent); }

  /* ---- objective + bomb status, top left ---- */
  #objective {
    position: fixed; top: 18px; left: 18px; max-width: 300px;
    padding: 10px 12px; background: #14161ad9; border: 1px solid var(--hairline);
    border-left: 2px solid var(--ct); border-radius: var(--radius);
  }
  #objective h2 { margin: 0 0 4px; font-size: 11px; letter-spacing: 0.14em; color: var(--muted); font-weight: 600; }
  #objective p { margin: 0; font-size: 14px; line-height: 1.35; }
  #objective.planted { border-left-color: var(--accent); }
  #objective.planted p { color: var(--accent); }

  /* ---- kill feed, top right ---- */
  #feed { position: fixed; top: 18px; right: 18px; display: grid; gap: 4px; justify-items: end; }
  #feed div {
    font-family: var(--font-readout); font-size: 12px; padding: 4px 8px;
    background: #14161ac9; border: 1px solid var(--hairline); border-radius: var(--radius);
    animation: feedIn 160ms ease-out;
  }
  #feed b { color: var(--accent); font-weight: 600; }
  @keyframes feedIn { from { opacity: 0; transform: translateX(8px); } }

  /* ---- vitals, bottom left ---- */
  #vitals {
    position: fixed; left: 18px; bottom: 18px; display: grid; gap: 6px; width: 210px;
    padding: 10px 12px; background: #14161ad9; border: 1px solid var(--hairline);
    border-radius: var(--radius); backdrop-filter: blur(6px);
  }
  .bar { height: 7px; background: #ffffff1f; border: 1px solid var(--hairline); border-radius: 2px; overflow: hidden; }
  .bar span { display: block; height: 100%; width: 100%; transition: width 90ms linear; }
  #health-bar span { background: var(--ink); }
  #health-bar.hurt span { background: var(--accent); }
  #armor-bar span { background: var(--ct); }
  .vital-row { display: flex; align-items: baseline; gap: 8px; font-family: var(--font-readout); }
  .vital-row b { font-size: 30px; font-weight: 600; letter-spacing: -0.03em; }
  .vital-row i { font-size: 11px; font-style: normal; color: var(--muted); letter-spacing: 0.1em; }

  /* ---- money + weapon, bottom right ---- */
  #wallet {
    position: fixed; right: 18px; bottom: 18px; text-align: right;
    font-family: var(--font-readout);
  }
  #money { font-size: 26px; font-weight: 600; letter-spacing: -0.02em; color: #8fd694; }
  #money.flash { color: var(--ink); }
  #weapon-name { font-size: 12px; letter-spacing: 0.1em; color: var(--muted); margin-top: 2px; }
  #ammo { display: flex; align-items: baseline; justify-content: flex-end; gap: 6px; margin-top: 2px; }
  #ammo-mag { font-size: 44px; line-height: 1; letter-spacing: -0.04em; }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 14px; color: var(--muted); }
  #grenades { font-size: 12px; color: var(--ink); letter-spacing: 0.08em; margin-top: 4px; }

  /* ---- defuse / plant progress ---- */
  #progress {
    position: fixed; left: 50%; bottom: 22%; transform: translateX(-50%);
    width: 240px; text-align: center; display: none;
  }
  #progress.on { display: block; }
  #progress p { margin: 0 0 6px; font-size: 12px; letter-spacing: 0.12em; color: var(--ink); }
  #progress .bar { height: 8px; }
  #progress .bar span { background: var(--accent); width: 0%; transition: none; }

  /* ---- buy menu ---- */
  #buy {
    position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%);
    width: min(560px, 92vw); padding: 20px;
    background: #14161af2; border: 1px solid var(--hairline); border-radius: 6px;
    pointer-events: auto; box-shadow: 0 24px 60px #00000080;
  }
  #buy[hidden] { display: none; }
  #buy header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 14px; }
  #buy h2 { margin: 0; font-size: 15px; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 600; }
  #buy header span { font-family: var(--font-readout); font-size: 20px; color: #8fd694; }
  #buy ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }
  #buy li {
    display: grid; grid-template-columns: 22px 1fr 54px 62px; align-items: center; gap: 10px;
    padding: 10px 12px; border: 1px solid var(--hairline); border-radius: var(--radius);
    background: #1e222899; cursor: pointer; transition: border-color 90ms, background-color 90ms;
  }
  #buy li:hover { border-color: var(--accent); background: #1e2228; }
  #buy li.cant { opacity: 0.42; cursor: not-allowed; }
  #buy li.owned { border-color: var(--ct); }
  #buy kbd {
    font-family: var(--font-readout); font-size: 11px; text-align: center; padding: 2px 0;
    border: 1px solid var(--hairline); border-radius: 2px; color: var(--muted);
  }
  #buy .item-name { font-size: 14px; }
  #buy .item-note { font-size: 11px; color: var(--muted); }
  #buy .item-note:not(:empty) { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  #buy .price { font-family: var(--font-readout); font-size: 14px; color: #8fd694; text-align: right; }
  #buy .owned-tag { font-size: 10px; letter-spacing: 0.1em; color: var(--ct); text-align: right; }
  #buy footer { margin-top: 14px; font-size: 12px; color: var(--muted); }

  /* ---- round banner ---- */
  /* Sits high and never over the crosshair: in a shooter the centre of the frame belongs to the
     sightline, so the banner lives above it and the shadow keeps it readable on any wall. */
  #banner {
    position: fixed; left: 0; right: 0; top: 15%; text-align: center; pointer-events: none;
    opacity: 0; transition: opacity 200ms ease;
    text-shadow: 0 2px 18px #0b0d10e6, 0 1px 3px #0b0d10cc;
  }
  #banner.on { opacity: 1; }
  #banner h1 { margin: 0; font-size: 40px; letter-spacing: 0.02em; font-weight: 600; text-wrap: balance; }
  #banner p { margin: 8px 0 0; font-size: 14px; color: var(--ink); opacity: 0.85; letter-spacing: 0.06em; }
  #banner.win h1 { color: var(--ct); }
  #banner.lose h1 { color: var(--accent); }

  /* ---- damage vignette ---- */
  #damage {
    position: fixed; inset: 0; pointer-events: none; opacity: 0;
    background: radial-gradient(ellipse at center, #ff3a1a00 42%, #c02f10b3 100%);
    transition: opacity 220ms ease-out;
  }

  /* ---- start overlay ---- */
  .overlay {
    position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: radial-gradient(ellipse at 50% 45%, #14161a4d 18%, #14161ac9 78%);
  }
  .overlay[hidden] { display: none; }
  .panel {
    width: min(520px, 100%); padding: 32px;
    background: #1e2228f2; border: 1px solid var(--hairline); border-radius: 6px;
    box-shadow: 0 30px 80px #00000099;
  }
  .panel .eyebrow { font-size: 11px; letter-spacing: 0.22em; color: var(--accent); margin: 0 0 10px; }
  .panel h1 { margin: 0 0 10px; font-size: 38px; line-height: 1.1; font-weight: 600; letter-spacing: -0.02em; text-wrap: balance; }
  .panel p { margin: 0 0 22px; max-width: 46ch; font-size: 15px; line-height: 1.55; color: var(--muted); }
  #play {
    font: inherit; font-weight: 600; padding: 12px 18px; white-space: nowrap;
    border: 1px solid var(--accent); border-radius: 8px; background: var(--accent);
    color: #14161a; cursor: pointer; transition: background-color 120ms;
  }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 22px 0 0; padding: 0; list-style: none; display: grid; gap: 7px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd {
    min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: 3px;
    font-family: var(--font-readout); font-size: 11px; color: var(--ink); text-align: center;
  }
  @media (prefers-reduced-motion: reduce) { * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; } }
</style>
</head>
<body>
<div id="game"></div>

<div id="hud" aria-hidden="true">
  <div id="crosshair"><i class="c-t"></i><i class="c-b"></i><i class="c-l"></i><i class="c-r"></i></div>

  <div id="topbar">
    <div class="team-score ct" id="score-ct">0</div>
    <div>
      <div class="team-tag">ROUND <span id="round-no">1</span></div>
      <div id="clock">1:45</div>
    </div>
    <div class="team-score t" id="score-t">0</div>
  </div>

  <div id="objective">
    <h2>OBJECTIVE</h2>
    <p id="objective-text">Defend the kiln yard. Hold both sites.</p>
  </div>

  <div id="feed"></div>

  <div id="vitals">
    <div class="vital-row"><b id="health">100</b><i>HEALTH</i></div>
    <div class="bar" id="health-bar"><span></span></div>
    <div class="vital-row" style="margin-top:2px"><b id="armor" style="font-size:18px">0</b><i>ARMOR</i></div>
    <div class="bar" id="armor-bar"><span style="width:0%"></span></div>
  </div>

  <div id="wallet">
    <div id="money">$800</div>
    <div id="weapon-name">PISTOL</div>
    <div id="ammo"><span id="ammo-mag">12</span><span id="ammo-reserve">/ 48</span></div>
