    <button id="play" type="button">Deploy</button>
    <ul class="keys">
      <li><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> Move · <kbd>Ctrl</kbd> Crouch</li>
      <li><kbd>Mouse</kbd> Look · <kbd>Click</kbd> Fire · <kbd>R</kbd> Reload</li>
      <li><kbd>B</kbd> Buy menu · <kbd>G</kbd> Frag · <kbd>E</kbd> Defuse</li>
      <li><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd> Switch weapon · <kbd>Space</kbd> Jump</li>
