  fire.position.set(-14.0, 1.4, -4.6);
  group.add(fire);

  const chimney = new THREE.PointLight(new THREE.Color(PALETTE.ember), 8, 12, 2);
  chimney.position.set(-17.5, 6.2, -8.5);
  group.add(chimney);

