const HEAD_HEIGHT = 1.58;
const TORSO_HEIGHT = 1.12;
const RADIUS = 0.36;
const WALK = 3.1;
const RUN = 4.35;
const SIGHT_RANGE = 46;
const HEARING_RANGE = 26;
